-- Atomic terminal registration and credential lifecycle commands.
-- Device credentials are generated by the API and only their SHA-256 hashes
-- are persisted. Terminal administration is OWNER-only and audited atomically.

GRANT SELECT, INSERT ON terminals TO marketfa_tenant_admin_owner;
GRANT UPDATE (credential_hash, status, revoked_at, last_seen_at)
  ON terminals TO marketfa_tenant_admin_owner;
GRANT SELECT ON terminal_assignments TO marketfa_tenant_admin_owner;
GRANT UPDATE (revoked_at) ON terminal_assignments
  TO marketfa_tenant_admin_owner;

CREATE POLICY tenant_admin_owner_terminal_read ON terminals
  FOR SELECT TO marketfa_tenant_admin_owner
  USING (tenant_id = app_current_tenant_id());

CREATE POLICY tenant_admin_owner_terminal_insert ON terminals
  FOR INSERT TO marketfa_tenant_admin_owner
  WITH CHECK (tenant_id = app_current_tenant_id());

CREATE POLICY tenant_admin_owner_terminal_update ON terminals
  FOR UPDATE TO marketfa_tenant_admin_owner
  USING (tenant_id = app_current_tenant_id())
  WITH CHECK (tenant_id = app_current_tenant_id());

CREATE POLICY tenant_admin_owner_terminal_assignment_update ON terminal_assignments
  FOR UPDATE TO marketfa_tenant_admin_owner
  USING (tenant_id = app_current_tenant_id())
  WITH CHECK (tenant_id = app_current_tenant_id());

CREATE OR REPLACE FUNCTION tenant_terminal_register(
  p_tenant_id UUID,
  p_store_id UUID,
  p_name TEXT,
  p_credential_hash BYTEA
)
RETURNS TABLE(
  terminal_id UUID,
  store_id UUID,
  name TEXT,
  status terminal_status,
  registered_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $function$
DECLARE
  actor_id UUID;
  actor_role tenant_role;
  new_terminal_id UUID;
  new_registered_at TIMESTAMPTZ;
  normalized_name TEXT;
BEGIN
  actor_id := public.app_current_user_id();
  normalized_name := btrim(p_name);

  IF actor_id IS NULL
     OR p_tenant_id IS NULL
     OR p_store_id IS NULL
     OR p_credential_hash IS NULL
     OR octet_length(p_credential_hash) <> 32
     OR normalized_name IS NULL
     OR length(normalized_name) NOT BETWEEN 1 AND 120
     OR public.app_current_tenant_id() IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'Invalid terminal registration input'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::TEXT, 0));

  SELECT membership.role
  INTO actor_role
  FROM public.tenant_memberships AS membership
  JOIN public.users AS account ON account.id = membership.user_id
  JOIN public.tenants AS tenant ON tenant.id = membership.tenant_id
  WHERE membership.tenant_id = p_tenant_id
    AND membership.user_id = actor_id
    AND membership.status = 'ACTIVE'
    AND account.status = 'ACTIVE'
    AND tenant.status = 'ACTIVE';

  IF NOT FOUND OR actor_role <> 'OWNER' THEN
    RAISE EXCEPTION 'Terminal administration permission denied'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.stores AS store
    WHERE store.tenant_id = p_tenant_id
      AND store.id = p_store_id
      AND store.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'Store is not active in this tenant'
      USING ERRCODE = '23503';
  END IF;

  INSERT INTO public.terminals (
    tenant_id, store_id, name, credential_hash, status
  )
  VALUES (
    p_tenant_id, p_store_id, normalized_name, p_credential_hash, 'ACTIVE'
  )
  RETURNING id, registered_at INTO new_terminal_id, new_registered_at;

  INSERT INTO public.audit_events (
    tenant_id, store_id, actor_user_id, action, entity_type, entity_id, metadata
  )
  VALUES (
    p_tenant_id, p_store_id, actor_id, 'tenant.terminal.register',
    'terminal', new_terminal_id,
    jsonb_build_object('name', normalized_name)
  );

  RETURN QUERY
  SELECT new_terminal_id, p_store_id, normalized_name, 'ACTIVE'::terminal_status,
         new_registered_at;
END;
$function$;

CREATE OR REPLACE FUNCTION tenant_terminal_rotate_credential(
  p_tenant_id UUID,
  p_terminal_id UUID,
  p_new_credential_hash BYTEA
)
RETURNS TABLE(
  terminal_id UUID,
  store_id UUID,
  name TEXT,
  status terminal_status,
  registered_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $function$
DECLARE
  actor_id UUID;
  actor_role tenant_role;
  target public.terminals%ROWTYPE;
BEGIN
  actor_id := public.app_current_user_id();

  IF actor_id IS NULL
     OR p_tenant_id IS NULL
     OR p_terminal_id IS NULL
     OR p_new_credential_hash IS NULL
     OR octet_length(p_new_credential_hash) <> 32
     OR public.app_current_tenant_id() IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'Invalid terminal credential-rotation context'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::TEXT, 0));

  SELECT membership.role
  INTO actor_role
  FROM public.tenant_memberships AS membership
  JOIN public.users AS account ON account.id = membership.user_id
  JOIN public.tenants AS tenant ON tenant.id = membership.tenant_id
  WHERE membership.tenant_id = p_tenant_id
    AND membership.user_id = actor_id
    AND membership.status = 'ACTIVE'
    AND account.status = 'ACTIVE'
    AND tenant.status = 'ACTIVE';

  IF NOT FOUND OR actor_role <> 'OWNER' THEN
    RAISE EXCEPTION 'Terminal administration permission denied'
      USING ERRCODE = '42501';
  END IF;

  SELECT terminal.*
  INTO target
  FROM public.terminals AS terminal
  WHERE terminal.tenant_id = p_tenant_id
    AND terminal.id = p_terminal_id
  FOR UPDATE;

  IF NOT FOUND OR target.status = 'REVOKED' THEN
    RETURN;
  END IF;

  UPDATE public.terminals AS terminal
  SET credential_hash = p_new_credential_hash
  WHERE terminal.tenant_id = p_tenant_id
    AND terminal.id = p_terminal_id;

  INSERT INTO public.audit_events (
    tenant_id, store_id, actor_user_id, action, entity_type, entity_id, metadata
  )
  VALUES (
    p_tenant_id, target.store_id, actor_id, 'tenant.terminal.credential.rotate',
    'terminal', target.id, jsonb_build_object('status', target.status)
  );

  RETURN QUERY
  SELECT target.id, target.store_id, target.name, target.status, target.registered_at;
END;
$function$;

CREATE OR REPLACE FUNCTION tenant_terminal_suspend(
  p_tenant_id UUID,
  p_terminal_id UUID
)
RETURNS TABLE(
  terminal_id UUID,
  store_id UUID,
  name TEXT,
  status terminal_status,
  registered_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $function$
DECLARE
  actor_id UUID;
  actor_role tenant_role;
  target public.terminals%ROWTYPE;
BEGIN
  actor_id := public.app_current_user_id();

  IF actor_id IS NULL
     OR p_tenant_id IS NULL
     OR p_terminal_id IS NULL
     OR public.app_current_tenant_id() IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'Invalid terminal suspension context'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::TEXT, 0));

  SELECT membership.role
  INTO actor_role
  FROM public.tenant_memberships AS membership
  JOIN public.users AS account ON account.id = membership.user_id
  JOIN public.tenants AS tenant ON tenant.id = membership.tenant_id
  WHERE membership.tenant_id = p_tenant_id
    AND membership.user_id = actor_id
    AND membership.status = 'ACTIVE'
    AND account.status = 'ACTIVE'
    AND tenant.status = 'ACTIVE';

  IF NOT FOUND OR actor_role <> 'OWNER' THEN
    RAISE EXCEPTION 'Terminal administration permission denied'
      USING ERRCODE = '42501';
  END IF;

  SELECT terminal.*
  INTO target
  FROM public.terminals AS terminal
  WHERE terminal.tenant_id = p_tenant_id
    AND terminal.id = p_terminal_id
  FOR UPDATE;

  IF NOT FOUND OR target.status = 'REVOKED' THEN
    RETURN;
  END IF;

  IF target.status = 'ACTIVE' THEN
    UPDATE public.terminals AS terminal
    SET status = 'SUSPENDED'
    WHERE terminal.tenant_id = p_tenant_id
      AND terminal.id = p_terminal_id;

    INSERT INTO public.audit_events (
      tenant_id, store_id, actor_user_id, action, entity_type, entity_id, metadata
    )
    VALUES (
      p_tenant_id, target.store_id, actor_id, 'tenant.terminal.suspend',
      'terminal', target.id, jsonb_build_object('old_status', target.status)
    );
  END IF;

  RETURN QUERY
  SELECT target.id, target.store_id, target.name,
         CASE WHEN target.status = 'ACTIVE' THEN 'SUSPENDED'::terminal_status
              ELSE target.status END,
         target.registered_at;
END;
$function$;

CREATE OR REPLACE FUNCTION tenant_terminal_activate(
  p_tenant_id UUID,
  p_terminal_id UUID
)
RETURNS TABLE(
  terminal_id UUID,
  store_id UUID,
  name TEXT,
  status terminal_status,
  registered_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $function$
DECLARE
  actor_id UUID;
  actor_role tenant_role;
  target public.terminals%ROWTYPE;
BEGIN
  actor_id := public.app_current_user_id();

  IF actor_id IS NULL
     OR p_tenant_id IS NULL
     OR p_terminal_id IS NULL
     OR public.app_current_tenant_id() IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'Invalid terminal activation context'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::TEXT, 0));

  SELECT membership.role
  INTO actor_role
  FROM public.tenant_memberships AS membership
  JOIN public.users AS account ON account.id = membership.user_id
  JOIN public.tenants AS tenant ON tenant.id = membership.tenant_id
  WHERE membership.tenant_id = p_tenant_id
    AND membership.user_id = actor_id
    AND membership.status = 'ACTIVE'
    AND account.status = 'ACTIVE'
    AND tenant.status = 'ACTIVE';

  IF NOT FOUND OR actor_role <> 'OWNER' THEN
    RAISE EXCEPTION 'Terminal administration permission denied'
      USING ERRCODE = '42501';
  END IF;

  SELECT terminal.*
  INTO target
  FROM public.terminals AS terminal
  WHERE terminal.tenant_id = p_tenant_id
    AND terminal.id = p_terminal_id
  FOR UPDATE;

  IF NOT FOUND OR target.status = 'REVOKED' THEN
    RETURN;
  END IF;

  IF target.status = 'SUSPENDED' THEN
    UPDATE public.terminals AS terminal
    SET status = 'ACTIVE'
    WHERE terminal.tenant_id = p_tenant_id
      AND terminal.id = p_terminal_id;

    INSERT INTO public.audit_events (
      tenant_id, store_id, actor_user_id, action, entity_type, entity_id, metadata
    )
    VALUES (
      p_tenant_id, target.store_id, actor_id, 'tenant.terminal.activate',
      'terminal', target.id, jsonb_build_object('old_status', target.status)
    );
  END IF;

  RETURN QUERY
  SELECT target.id, target.store_id, target.name,
         CASE WHEN target.status = 'SUSPENDED' THEN 'ACTIVE'::terminal_status
              ELSE target.status END,
         target.registered_at;
END;
$function$;

CREATE OR REPLACE FUNCTION tenant_terminal_revoke(
  p_tenant_id UUID,
  p_terminal_id UUID
)
RETURNS TABLE(
  terminal_id UUID,
  store_id UUID,
  name TEXT,
  status terminal_status,
  registered_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $function$
DECLARE
  actor_id UUID;
  actor_role tenant_role;
  target public.terminals%ROWTYPE;
  final_revoked_at TIMESTAMPTZ;
BEGIN
  actor_id := public.app_current_user_id();

  IF actor_id IS NULL
     OR p_tenant_id IS NULL
     OR p_terminal_id IS NULL
     OR public.app_current_tenant_id() IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'Invalid terminal revocation context'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::TEXT, 0));

  SELECT membership.role
  INTO actor_role
  FROM public.tenant_memberships AS membership
  JOIN public.users AS account ON account.id = membership.user_id
  JOIN public.tenants AS tenant ON tenant.id = membership.tenant_id
  WHERE membership.tenant_id = p_tenant_id
    AND membership.user_id = actor_id
    AND membership.status = 'ACTIVE'
    AND account.status = 'ACTIVE'
    AND tenant.status = 'ACTIVE';

  IF NOT FOUND OR actor_role <> 'OWNER' THEN
    RAISE EXCEPTION 'Terminal administration permission denied'
      USING ERRCODE = '42501';
  END IF;

  SELECT terminal.*
  INTO target
  FROM public.terminals AS terminal
  WHERE terminal.tenant_id = p_tenant_id
    AND terminal.id = p_terminal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF target.status = 'REVOKED' THEN
    terminal_id := target.id;
    store_id := target.store_id;
    name := target.name;
    status := target.status;
    registered_at := target.registered_at;
    revoked_at := target.revoked_at;
    RETURN NEXT;
    RETURN;
  END IF;

  UPDATE public.terminals AS terminal
  SET status = 'REVOKED',
      revoked_at = statement_timestamp()
  WHERE terminal.tenant_id = p_tenant_id
    AND terminal.id = p_terminal_id
  RETURNING terminal.revoked_at INTO final_revoked_at;

  UPDATE public.terminal_assignments AS assignment
  SET revoked_at = statement_timestamp()
  WHERE assignment.tenant_id = p_tenant_id
    AND assignment.terminal_id = p_terminal_id
    AND assignment.revoked_at IS NULL;

  INSERT INTO public.audit_events (
    tenant_id, store_id, actor_user_id, action, entity_type, entity_id, metadata
  )
  VALUES (
    p_tenant_id, target.store_id, actor_id, 'tenant.terminal.revoke',
    'terminal', target.id, jsonb_build_object('old_status', target.status)
  );

  RETURN QUERY
  SELECT target.id, target.store_id, target.name, 'REVOKED'::terminal_status,
         target.registered_at, final_revoked_at;
END;
$function$;

GRANT CREATE ON SCHEMA public TO marketfa_tenant_admin_owner;
ALTER FUNCTION tenant_terminal_register(UUID, UUID, TEXT, BYTEA)
  OWNER TO marketfa_tenant_admin_owner;
ALTER FUNCTION tenant_terminal_rotate_credential(UUID, UUID, BYTEA)
  OWNER TO marketfa_tenant_admin_owner;
ALTER FUNCTION tenant_terminal_suspend(UUID, UUID)
  OWNER TO marketfa_tenant_admin_owner;
ALTER FUNCTION tenant_terminal_activate(UUID, UUID)
  OWNER TO marketfa_tenant_admin_owner;
ALTER FUNCTION tenant_terminal_revoke(UUID, UUID)
  OWNER TO marketfa_tenant_admin_owner;
REVOKE CREATE ON SCHEMA public FROM marketfa_tenant_admin_owner;

REVOKE ALL ON FUNCTION tenant_terminal_register(UUID, UUID, TEXT, BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION tenant_terminal_rotate_credential(UUID, UUID, BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION tenant_terminal_suspend(UUID, UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION tenant_terminal_activate(UUID, UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION tenant_terminal_revoke(UUID, UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION tenant_terminal_register(UUID, UUID, TEXT, BYTEA) TO marketfa_app;
GRANT EXECUTE ON FUNCTION tenant_terminal_rotate_credential(UUID, UUID, BYTEA) TO marketfa_app;
GRANT EXECUTE ON FUNCTION tenant_terminal_suspend(UUID, UUID) TO marketfa_app;
GRANT EXECUTE ON FUNCTION tenant_terminal_activate(UUID, UUID) TO marketfa_app;
GRANT EXECUTE ON FUNCTION tenant_terminal_revoke(UUID, UUID) TO marketfa_app;
